PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
DROP TABLE IF EXISTS "users";
CREATE TABLE users(id TEXT PRIMARY KEY,name TEXT NOT NULL,email TEXT UNIQUE NOT NULL,phone TEXT UNIQUE NOT NULL,address TEXT NOT NULL DEFAULT '',password TEXT NOT NULL, locked INTEGER NOT NULL DEFAULT 0);
DROP TABLE IF EXISTS "products";
CREATE TABLE products(id INTEGER PRIMARY KEY,data TEXT NOT NULL,stock INTEGER NOT NULL CHECK(stock>=0),active INTEGER NOT NULL DEFAULT 1);
INSERT INTO "products"(id,data,stock,active) VALUES(1,'{"id":1,"name":"Strawberry little love","type":"Bánh kem","note":"Dâu tươi · kem vanilla · một chút yêu","description":"Bánh kem dâu với cốt bông lan mềm, kem vanilla và dâu tươi. Một chiếc bánh dịu dàng cho những dịp đặc biệt.","ingredients":"Bột mì, trứng, sữa, bơ, kem sữa, dâu tươi","allergens":"Có gluten, trứng và sữa.","storage":"Bảo quản lạnh 2–6°C, dùng trong 24 giờ.","price":185000,"img":"berry.jpg"}',20,1);
INSERT INTO "products"(id,data,stock,active) VALUES(2,'{"id":2,"name":"Chocolate daydream","type":"Bánh kem","note":"Chocolate đậm · mềm tan · thật chiều lòng","description":"Cốt bánh chocolate mềm phủ ganache đậm vị, trang trí trái cây. Dành cho những người yêu vị cacao nguyên bản.","ingredients":"Bột mì, trứng, bơ, chocolate, kem sữa, trái cây","allergens":"Có gluten, trứng, sữa; có thể chứa hạt.","storage":"Bảo quản lạnh 2–6°C, dùng trong 24 giờ.","price":225000,"img":"hero.jpg"}',15,1);
INSERT INTO "products"(id,data,stock,active) VALUES(3,'{"id":3,"name":"A slice of sunshine","type":"Bánh ngọt","note":"Cốt bánh mềm · kem tươi · nắng dịu dàng","description":"Một phần bánh vanilla nhiều lớp với kem tươi và sốt quả mọng. Vừa đủ ngọt cho giờ trà chiều.","ingredients":"Bột mì, trứng, sữa, kem tươi, vanilla, quả mọng","allergens":"Có gluten, trứng và sữa.","storage":"Bảo quản lạnh 2–6°C, dùng trong 24 giờ.","price":65000,"img":"cake.jpg"}',30,1);
INSERT INTO "products"(id,data,stock,active) VALUES(4,'{"id":4,"name":"Bonjour, sweet morning","type":"Bánh nướng","note":"Bánh nướng thơm · trái cây · buổi sáng chậm","description":"Bánh ngàn lớp bơ thơm, nướng vàng giòn mỗi sáng, ăn kèm trái cây theo mùa.","ingredients":"Bột mì, bơ, sữa, trứng, men, trái cây","allergens":"Có gluten, trứng và sữa.","storage":"Dùng trong ngày; có thể hâm nóng nhẹ trước khi ăn.","price":75000,"img":"toast.jpg"}',25,1);
DROP TABLE IF EXISTS "cart";
CREATE TABLE cart(user_id TEXT REFERENCES users(id),product_id INTEGER REFERENCES products(id),qty INTEGER NOT NULL CHECK(qty>0),PRIMARY KEY(user_id,product_id));
DROP TABLE IF EXISTS "favorites";
CREATE TABLE favorites(user_id TEXT REFERENCES users(id),product_id INTEGER REFERENCES products(id),PRIMARY KEY(user_id,product_id));
DROP TABLE IF EXISTS "orders";
CREATE TABLE orders(id TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id),created TEXT NOT NULL,status TEXT NOT NULL,payment TEXT NOT NULL,payment_status TEXT NOT NULL,shipping TEXT NOT NULL,items TEXT NOT NULL,subtotal INTEGER NOT NULL,fee INTEGER NOT NULL,total INTEGER NOT NULL,request_key TEXT NOT NULL,UNIQUE(user_id,request_key));
DROP TABLE IF EXISTS "order_events";
CREATE TABLE order_events(id INTEGER PRIMARY KEY,order_id TEXT REFERENCES orders(id),status TEXT NOT NULL,created TEXT NOT NULL);
DROP TABLE IF EXISTS "reviews";
CREATE TABLE reviews(id TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id),product_id INTEGER REFERENCES products(id),rating INTEGER NOT NULL CHECK(rating BETWEEN 1 AND 5),content TEXT NOT NULL,created TEXT NOT NULL,reply TEXT,UNIQUE(user_id,product_id));
DROP TABLE IF EXISTS "payment_attempts";
CREATE TABLE payment_attempts(id TEXT PRIMARY KEY,user_id TEXT REFERENCES users(id),data TEXT NOT NULL,status TEXT NOT NULL,expires INTEGER NOT NULL,request_key TEXT NOT NULL,UNIQUE(user_id,request_key));
DROP TABLE IF EXISTS "staff";
CREATE TABLE staff(id TEXT PRIMARY KEY,name TEXT NOT NULL,email TEXT UNIQUE NOT NULL,phone TEXT NOT NULL DEFAULT '',role TEXT NOT NULL CHECK(role IN ('admin','staff')),perms TEXT NOT NULL DEFAULT '[]',password TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,created TEXT NOT NULL);
